import os
from typing import Any, Dict, Optional

from huggingface_hub import InferenceClient


def _extract_text(response: Any) -> str:
    if response is None:
        return ""
    if isinstance(response, str):
        return response
    if isinstance(response, list):
        parts = []
        for item in response:
            if isinstance(item, dict):
                if "generated_text" in item:
                    parts.append(str(item["generated_text"]))
                elif "text" in item:
                    parts.append(str(item["text"]))
                elif "content" in item:
                    parts.append(str(item["content"]))
            else:
                parts.append(str(item))
        return "".join(parts).strip()
    if isinstance(response, dict):
        for key in ("generated_text", "text", "content", "message"):
            if key in response:
                return str(response[key])
        return str(response)
    return str(response)


def resolve_and_invoke_model(
    prompt: str,
    model: Optional[str] = None,
    provider: Optional[str] = None,
    **generation_kwargs: Any,
) -> Dict[str, Any]:
    hf_token = os.getenv("HF_TOKEN")
    if not hf_token:
        raise RuntimeError("HF_TOKEN environment variable is required for Hugging Face Inference Providers.")

    resolved_model = model or os.getenv("HF_MODEL_ID") or "meta-llama/Llama-3.1-8B-Instruct"
    resolved_provider = provider or os.getenv("HF_INFERENCE_PROVIDER") or "auto"

    client = InferenceClient(
        model=resolved_model,
        provider=resolved_provider,
        token=hf_token,
    )

    response = client.text_generation(
        prompt,
        max_new_tokens=generation_kwargs.pop("max_new_tokens", 128),
        temperature=generation_kwargs.pop("temperature", 0.7),
        do_sample=generation_kwargs.pop("do_sample", True),
        **generation_kwargs,
    )

    return {
        "provider": "huggingface_hub",
        "model": resolved_model,
        "inference_provider": resolved_provider,
        "output_text": _extract_text(response),
        "raw_response": response,
    }
